record.field:
[
    {
        "when": "WhatsApp prospect shows commercial intent but phone not yet known",
        "steps": [
            "Ask: '¿Me podés compartir tu número de teléfono para que te contactemos?'",
            "Wait for customer reply with phone number",
            "Then call create_lead with the phone they provided"
        ],
        "call": {
            "name": "create_lead",
            "arguments": {
                "name": "Interesado en Yamaha FZ - financiacion",
                "contact_name": "Martin",
                "phone": "5491122334455",
                "description": "Cliente quiere financiacion para Yamaha FZ y pide avanzar hoy.",
                "intent_signal": "Pidio avanzar con propuesta de financiacion",
                "lead_temperature": "hot",
                "sentiment_summary": "Motivado, listo para avanzar",
                "next_action": "Enviar propuesta y llamar en el dia"
            }
        }
    },
    {
        "when": "WhatsApp prospect shows commercial intent and already gave phone in conversation",
        "call": {
            "name": "create_lead",
            "arguments": {
                "name": "Interesado en Honda XR300",
                "contact_name": "Franco",
                "phone": "5492611234567",
                "description": "Cliente interesado en XR300, quiere prueba de manejo mañana.",
                "intent_signal": "Agendo prueba de manejo para mañana",
                "lead_temperature": "hot",
                "next_action": "Confirmar turno prueba de manejo"
            }
        }
    },
    {
        "when": "Telegram user only asks general info and no follow-up intent",
        "call": "Do not call create_lead yet"
    }
]

{
    "name": "create_lead",
    "description": "Create or update a qualified lead/opportunity in CRM",
    "parameters": {
        "type": "object",
        "properties": {
            "name": {
                "type": "string",
                "description": "Lead title or opportunity name"
            },
            "contact_name": {
                "type": "string",
                "description": "Contact person name"
            },
            "email": {
                "type": "string",
                "description": "Email address"
            },
            "phone": {
                "type": "string",
                "description": "Phone number. For WhatsApp/Evolution channels the platform does NOT provide this automatically — ask the customer for it during the conversation before calling this tool."
            },
            "description": {
                "type": "string",
                "description": "Conversation summary and customer need"
            },
            "intent_signal": {
                "type": "string",
                "description": "Short reason why this is commercially qualified"
            },
            "lead_temperature": {
                "type": "string",
                "description": "Lead temperature: cold, warm, or hot"
            },
            "sentiment_summary": {
                "type": "string",
                "description": "Short customer sentiment summary"
            },
            "preferred_contact_time": {
                "type": "string",
                "description": "Best time window to contact the customer"
            },
            "next_action": {
                "type": "string",
                "description": "Next commercial action agreed with customer"
            }
        },
        "required": ["name"]
    }
}
